"""只向独立 F 包加入自建图片导入入口；生产相册选择、预处理、发送不替换。"""
def instrument(app):
    if ".id('test-seed-photos')" in (app/'entry/src/main/ets/pages/Index.ets').read_text(): return
    from generate_photo_fixtures import generate
    raw=app/'entry/src/main/resources/rawfile';raw.mkdir(parents=True,exist_ok=True);generate(raw)
    p=app/'entry/src/main/ets/pages/Index.ets';s=p.read_text()
    s="import { photoAccessHelper } from '@kit.MediaLibraryKit';\nimport { fileIo as photoFs, fileUri } from '@kit.CoreFileKit';\n"+s
    s=s.replace("  @State private startupPhase:","  @State private photoSeedStatus: string = 'seed';\n  @State private photoSeedUris: string = '';\n  private async seedTestPhotos(): Promise<void> {\n    if (!this.context || this.photoSeedStatus !== 'seed') { return; }\n    this.photoSeedStatus = 'importing';\n    const helper = photoAccessHelper.getPhotoAccessHelper(this.context);\n    try {\n      const paths: string[] = []; const uris: string[] = []; const configs: photoAccessHelper.PhotoCreationConfig[] = [];\n      for (let n = 1; n <= 3; n++) {\n        const bytes = await this.context.resourceManager.getRawFileContent('orientation-fixtures/exif-' + n + '.jpg');\n        const path = this.context.cacheDir + '/harmony-owned-photo-' + n + '.jpg';\n        const file = await photoFs.open(path, photoFs.OpenMode.CREATE | photoFs.OpenMode.READ_WRITE | photoFs.OpenMode.TRUNC);\n        try { await photoFs.write(file.fd, bytes.buffer); } finally { await photoFs.close(file); }\n        paths.push(path); uris.push(fileUri.getUriFromPath(path));\n        configs.push({ title: 'harmony-owned-photo-' + n, fileNameExtension: 'jpg', photoType: photoAccessHelper.PhotoType.IMAGE });\n      }\n      const destinations = await helper.showAssetsCreationDialog(uris, configs);\n      this.photoSeedUris = JSON.stringify(destinations);\n      for (let n = 0; n < destinations.length; n++) {\n        const input = await photoFs.open(paths[n], photoFs.OpenMode.READ_ONLY);\n        const output = await photoFs.open(destinations[n], photoFs.OpenMode.WRITE_ONLY);\n        try { await photoFs.copyFile(input.fd, output.fd); } finally { await photoFs.close(input); await photoFs.close(output); }\n      }\n      this.photoSeedStatus = 'seeded-' + destinations.length;\n    } catch (e) { this.photoSeedStatus = 'failed-' + JSON.stringify(e); } finally { await helper.release(); }\n  }\n  @State private startupPhase:",1)
    marker="    Column() {\n      if (this.errorText)";assert marker in s
    s=s.replace(marker,"    Column() {\n      Text(this.photoSeedStatus).id('test-seed-photos').fontSize(8).height(16).width('100%').onClick(() => this.seedTestPhotos())\n      Text(this.photoSeedUris).id('test-photo-uris').fontSize(1).height(1).width('100%')\n      if (this.errorText)",1);p.write_text(s)
